import { Pcm16Resampler, SentenceTTS, SharedInstances } from '@micdrop/server'
import {
  QwenLanguage,
  QwenLanguageCode,
  QwenSpeaker,
  resolveLanguage,
} from './voices'

/**
 * Local Qwen3-TTS text to speech, generated by an mlx-audio server running
 * next to your app. Nothing leaves the machine and there is no API key.
 *
 * Qwen3-TTS is the only local voice in Micdrop that speaks ten languages with
 * one checkpoint, French and Spanish included. It accepts an instruction
 * ("Very happy", "speak slowly") that changes how a sentence is read. It
 * generates audio with a language model, so it needs Apple Silicon or a GPU,
 * while Piper and Kokoro run on any CPU.
 *
 * The server is started separately and holds the weights, see the README. Any
 * server answering the OpenAI speech route with raw PCM works in its place.
 *
 * @see https://github.com/QwenLM/Qwen3-TTS
 * @see https://github.com/Blaizzy/mlx-audio
 */

export interface Qwen3TTSOptions {
  /** Address of the mlx-audio server, `http://localhost:8000` by default. */
  url?: string

  /** Checkpoint the server loads, a CustomVoice one by default. */
  model?: string

  /** Preset speaker of the CustomVoice checkpoints. */
  voice?: QwenSpeaker | (string & {})

  /**
   * Language of the text, as a code (`"fr"`), a locale (`"fr-FR"`) or the name
   * the checkpoint uses (`"french"`). Detected from the text when missing, or
   * when it is not one of the ten supported languages.
   */
  language?: QwenLanguageCode | QwenLanguage | (string & {})

  /**
   * How the sentence is read ("Very happy", "speak slowly"), or, on a
   * VoiceDesign checkpoint, a description of the voice to generate.
   */
  instruct?: string

  /** Path, on the server, to a few seconds of speech to clone. */
  refAudio?: string

  /** What the reference audio says, needed for the clone to be faithful. */
  refText?: string

  /** Audio generated before a chunk is sent, in seconds. */
  streamingInterval?: number

  /** Sampling temperature, above 1 for a more variable delivery. */
  temperature?: number

  /** Sampling window, in number of candidates. */
  topK?: number

  /** Sampling window, in cumulated probability. */
  topP?: number

  /** Penalty applied to repeated audio tokens, which keeps a voice on track. */
  repetitionPenalty?: number

  /** Ceiling on the audio tokens of one sentence, 12.5 of them per second. */
  maxTokens?: number

  /** Loads the checkpoint on the server at startup, on by default. */
  warmup?: boolean
}

const DEFAULT_URL = 'http://localhost:8000'
const DEFAULT_MODEL = 'mlx-community/Qwen3-TTS-12Hz-1.7B-CustomVoice-6bit'
const DEFAULT_VOICE: QwenSpeaker = 'Ryan'
const DEFAULT_STREAMING_INTERVAL = 0.5 // Seconds of audio per chunk

// Sampling defaults of the model itself. The mlx-audio server defaults to a
// repetition penalty of 1, which can make the model repeat audio and turn a
// short sentence into a minute and a half of audio.
const DEFAULT_TEMPERATURE = 0.9
const DEFAULT_TOP_K = 50
const DEFAULT_TOP_P = 1
const DEFAULT_REPETITION_PENALTY = 1.05
// A sentence is a few dozen tokens. 500 is enough for a long sentence and
// still stops a generation that does not end.
const DEFAULT_MAX_TOKENS = 500

const QWEN_SAMPLE_RATE = 24000 // Rate of the audio Qwen3-TTS generates
const OUTPUT_SAMPLE_RATE = 16000 // Rate expected by the Micdrop client

/**
 * Server and checkpoint pairs already warmed up in this process.
 *
 * One instance is built per call, and the server keeps the checkpoint loaded
 * for all of them. Warming up on every call would make the server generate an
 * extra word while other calls wait. If the server was down during the first
 * warm-up, the next call tries again.
 */
const warmups = new SharedInstances<void>()

export class Qwen3TTS extends SentenceTTS {
  constructor(private readonly options: Qwen3TTSOptions = {}) {
    super()

    if (options.warmup !== false) {
      // The first load of the checkpoint can take close to a minute. Doing it
      // now keeps that delay out of the first answer.
      warmups
        .load(
          [options.url ?? DEFAULT_URL, options.model ?? DEFAULT_MODEL],
          () =>
            this.request('Hello.', new AbortController().signal).then(
              async (response) => {
                await response.arrayBuffer()
              }
            )
        )
        .then(() => this.log('Model warmed up'))
        .catch((error) => {
          console.error('[Qwen3TTS] Failed to warm the model up:', error)
        })
    }
  }

  protected async synthesize(
    text: string,
    signal: AbortSignal
  ): Promise<Buffer | undefined> {
    const response = await this.request(text, signal)
    const body = response.body
    if (!body) throw new Error('Qwen3-TTS server answered without a body')

    // One resampler per sentence. The chunks of a sentence form one continuous
    // stream, but two sentences are independent, so the fractional position
    // must not carry over from one to the next.
    const resampler = new Pcm16Resampler(QWEN_SAMPLE_RATE, OUTPUT_SAMPLE_RATE)
    const reader = body.getReader()

    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      // Chunks are emitted as they arrive, so playback starts before the
      // sentence is fully generated
      if (!this.emitAudio(resampler.process(Buffer.from(value)))) {
        // The utterance was cancelled or replaced. Closing the body closes the
        // connection, and the server stops generating.
        await reader.cancel()
        break
      }
    }

    return undefined
  }

  private async request(text: string, signal: AbortSignal): Promise<Response> {
    const { options } = this
    const url = `${(options.url ?? DEFAULT_URL).replace(/\/+$/, '')}/v1/audio/speech`

    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal,
      body: JSON.stringify({
        model: options.model ?? DEFAULT_MODEL,
        input: text,
        voice: options.voice ?? DEFAULT_VOICE,
        // The checkpoint reads "auto" as "guess from the text"
        lang_code: resolveLanguage(options.language),
        instruct: options.instruct,
        ref_audio: options.refAudio,
        ref_text: options.refText,
        temperature: options.temperature ?? DEFAULT_TEMPERATURE,
        top_k: options.topK ?? DEFAULT_TOP_K,
        top_p: options.topP ?? DEFAULT_TOP_P,
        repetition_penalty:
          options.repetitionPenalty ?? DEFAULT_REPETITION_PENALTY,
        max_tokens: options.maxTokens ?? DEFAULT_MAX_TOKENS,
        // Raw PCM16 rather than wav, so chunks can be concatenated without a
        // header in the middle of the audio
        response_format: 'pcm',
        stream: true,
        streaming_interval:
          options.streamingInterval ?? DEFAULT_STREAMING_INTERVAL,
      }),
    })

    if (!response.ok) {
      const details = await response.text().catch(() => '')
      throw new Error(
        `Qwen3-TTS server answered ${response.status} ${response.statusText}: ${details}`
      )
    }

    return response
  }
}
